check_nested_weak_encryption(node, depth, max_depth) {
    depth < max_depth
    node.ir_type == "Hash"
    some key, val
    node.value[key] = val
    is_weak_encryption_attribute(key, val)
} else {
    depth < max_depth
    node.ir_type == "Array"
    some member
    member = node.value[_]
    check_nested_weak_encryption(member, depth + 1, max_depth)
} else {
    depth < max_depth
    node.ir_type == "MethodCall"
    check_nested_weak_encryption(node.receiver, depth + 1, max_depth)
} else {
    depth < max_depth
    node.ir_type == "BlockExpr"
    some stmt
    stmt = node.statements[_]
    check_nested_weak_encryption(stmt, depth + 1, max_depth)
}

