is_disabled_encryption(attr_name, attr_value, all_attrs) {
    attr_name == "enabled"
    attr_value.ir_type == "Boolean"
    attr_value.value == false
    some other_attr
    other_attr = all_attrs[_]
    other_attr != attr_name
    contains_encryption_keyword(other_attr)
}

